(()=>{'use strict';
const {chapters,lessons}=window.COURSE,byId=Object.fromEntries(lessons.map(l=>[l.id,l])),qById=Object.fromEntries(lessons.flatMap(l=>l.quiz.map(q=>[q.id,{...q,lesson:l}]))),KEY='zhiwei-calculus-v1';
const paths={home:'M3 10 10 3l7 7M5 9v8h10V9M8 17v-5h4v5',book:'M10 5c-3-2-6-2-8-1v12c3-1 5-1 8 1m0-12c3-2 6-2 8-1v12c-3-1-5-1-8 1V5',lab:'M7 2h6M8 2v6l-5 8c-1 2 1 2 2 2h10c2 0 3 0 2-2l-5-8V2M6 12h8',pen:'m13 3 4 4M3 13l10-10c1-1 2-1 3 0l1 1c1 1 1 2 0 3L7 17l-5 1 1-5ZM11 18h7',formula:'M16 3H7L3 10l4 7h9M5 10h8',bookmark:'M5 3h10v15l-5-4-5 4V3Z',search:'m14 14 4 4M15 9a6 6 0 1 1-12 0 6 6 0 0 1 12 0',arrow:'M4 10h12m-5-5 5 5-5 5',chevron:'m8 5 5 5-5 5',check:'m4 10 4 4 8-9',calendar:'M5 2v4m10-4v4M3 8h14M4 4h12c1 0 1 1 1 2v11H3V6c0-1 0-2 1-2Z',bulb:'M7 15h6m-6 3h6M6 12c-5-5-1-10 4-10s9 5 4 10l-1 3H7l-1-3Z',clock:'M10 6v4l3 2M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',menu:'M3 5h14M3 10h14M3 15h14',info:'M10 9v6m0-10h.01M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',chart:'M3 3v14h14M6 13l4-5 3 2 4-5',download:'M10 2v11m-4-4 4 4 4-4M3 14v4h14v-4',back:'M16 10H4m5-5-5 5 5 5',close:'m5 5 10 10M15 5 5 15'};
function icon(n){return `<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const blank=()=>({completed:[],bookmarks:[],answers:{},last:'1-1',activity:{}});
let state=blank(),volume='all',reviewTab='wrong',practiceCh=1,practiceType='all',formulaCh=0,labType='limit';
try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v&&typeof v==='object'){state={...blank(),...v};state.completed=Array.isArray(v.completed)?v.completed.filter(id=>byId[id]):[];state.bookmarks=Array.isArray(v.bookmarks)?v.bookmarks.filter(id=>byId[id]):[];state.answers=Object.fromEntries(Object.entries(v.answers||{}).filter(([id,a])=>qById[id]&&a&&typeof a.correct==='boolean'));if(!byId[state.last])state.last='1-1';if(!state.activity||typeof state.activity!=='object')state.activity={};}}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('浏览器暂不能保存进度，请保留当前页面。')}}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2800)}
const wrong=()=>Object.keys(state.answers).filter(id=>!state.answers[id].correct);
const progress=c=>c.lessons.filter(id=>state.completed.includes(id)).length;
const pct=(a,b)=>b?Math.round(a/b*100):0;
const route=()=>location.hash.slice(1)||'home';
const symbols=['lim','f ′','f ″','∫','∫ₐᵇ','πr²','dy/dx','a · b','∇f','∬','∮','∑'];
function sidebar(){let active=route().split('/')[0];if(['chapter','lesson'].includes(active))active='courses';document.getElementById('sidebar').innerHTML=`<a class="brand" href="#home" aria-label="知微首页"><span class="brand-symbol">∂</span><div><div class="brand-name">知微</div><div class="brand-sub">CALCULUS LAB</div></div></a><div class="nav-label">学习空间</div><nav class="nav" aria-label="主导航">${[['home','home','学习概览'],['courses','book','课程目录'],['lab','lab','交互实验室'],['practice','pen','随堂练习'],['formulas','formula','公式手册'],['review','bookmark','错题与收藏']].map(([id,ic,label])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='review'&&wrong().length?`<span class="badge">${wrong().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-divider"></div><div class="nav-label">课程体系</div><div class="side-course"><a href="#courses/upper"><i></i>上册 · 一元函数微积分</a><a href="#courses/lower"><i class="green"></i>下册 · 多元函数与级数</a></div><div class="sidebar-bottom"><div class="side-progress"><span class="muted">我的学习进度</span><span>${pct(state.completed.length,lessons.length)}%</span></div><div class="bar" role="progressbar" aria-label="总学习进度" aria-valuenow="${state.completed.length}" aria-valuemin="0" aria-valuemax="82"><b style="width:${pct(state.completed.length,82)}%"></b></div><a href="#progress" class="side-note">${icon('chart')}已学习 ${state.completed.length} / 82 节　${icon('chevron')}</a></div>`;
const names={home:'学习概览',courses:'课程目录',chapter:'课程目录',lesson:'正在学习',lab:'交互实验室',practice:'随堂练习',formulas:'公式手册',review:'错题与收藏',about:'关于课程',progress:'学习进度'};
document.getElementById('topbar').innerHTML=`<button class="mobile-toggle" data-action="menu" aria-label="打开导航" aria-expanded="false">${icon('menu')}</button><div class="crumb"><span class="crumb-root">我的学习</span><span>/</span><b>${names[route().split('/')[0]]||'学习空间'}</b></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search')}<span>搜索知识点…</span><kbd>⌘ K</kbd></button><a class="avatar" href="#progress" aria-label="查看学习进度">学</a></div>`;}
function math(root=document.getElementById('main')){if(!window.katex)return;root.querySelectorAll('[data-formula]').forEach(el=>{try{katex.render(el.dataset.formula,el,{displayMode:true,throwOnError:true,strict:'ignore'})}catch(e){el.textContent=el.dataset.formula;el.dataset.mathError=e.message}});const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.nodeValue.includes('$')&&!n.parentElement.closest('.katex,script,style,textarea,input,[data-formula]')?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT});let nodes=[],n;while(n=walker.nextNode())nodes.push(n);nodes.forEach(node=>{let text=node.nodeValue,re=/\$([^$]+)\$/g,m,last=0,frag=document.createDocumentFragment();while(m=re.exec(text)){frag.append(text.slice(last,m.index));let span=document.createElement('span');try{katex.render(m[1],span,{throwOnError:true,strict:'ignore'})}catch(e){span.textContent=m[1];span.dataset.mathError=e.message}frag.append(span);last=re.lastIndex}if(last){frag.append(text.slice(last));node.replaceWith(frag)}})}
function fbox(f){return `<div class="formula-box" data-formula="${esc(f)}"></div>`}
function chapterCard(c){let p=progress(c);return `<a href="#chapter/${c.id}" class="chapter-card"><div class="chapter-card-top"><span class="chapter-number">CHAPTER ${String(c.id).padStart(2,'0')}</span><span class="chapter-mark">${symbols[c.id-1]}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="chapter-card-bottom"><span>${c.lessons.length} 节课程 · ${p?`已学 ${p} 节`:'未开始'}</span>${icon('arrow')}</div><div class="bar"><b style="width:${pct(p,c.lessons.length)}%"></b></div></a>`}
function heroArt(){let lines='';const proj=(x,y)=>{let z=1.15*Math.sin(x*.8)*Math.cos(y*.6);return [212+43*x-25*y,168+15*x+13*y-44*z]};for(let k=0;k<2;k++)for(let i=-14;i<=14;i++){let pts=[];for(let j=-50;j<=50;j++){let a=i/5,b=j/17;let p=k?proj(b,a):proj(a,b);pts.push(p.map(v=>v.toFixed(1)).join(','))}lines+=`<polyline points="${pts.join(' ')}" fill="none" stroke="${k?'#7595d8':'#4a73c6'}" stroke-width="${i===0?1.3:.65}" opacity="${k?.3:.55}"/>`}return `<svg viewBox="0 0 435 320" aria-hidden="true"><defs><radialGradient id="glow"><stop stop-color="#c5d7ff" stop-opacity=".6"/><stop offset="1" stop-color="#edf1fc" stop-opacity="0"/></radialGradient></defs><ellipse cx="230" cy="167" rx="220" ry="148" fill="url(#glow)"/><path d="M48 230h350M223 54v239" fill="none" stroke="#b9c7e5" stroke-dasharray="3 5" stroke-width=".7"/>${lines}<text x="351" y="252" font-size="12" font-style="italic" font-family="Georgia" fill="#8ca1c9">x</text><text x="230" y="64" font-size="12" font-style="italic" font-family="Georgia" fill="#8ca1c9">z</text><g transform="translate(264 38)"><rect width="107" height="40" rx="8" fill="white" fill-opacity=".7" stroke="#dfe6f5"/><text x="53" y="26" text-anchor="middle" font-size="16" fill="#5c7bc0" font-family="Georgia" font-style="italic">∂f / ∂x</text></g><circle cx="214" cy="166" r="4" fill="#3158c9"/><circle cx="214" cy="166" r="8" fill="none" stroke="#3158c9" opacity=".2"/></svg><span class="art-caption">A small change. A deeper understanding.</span>`}
function home(){const l=byId[state.last],c=chapters[l.chapter-1];const date=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());return `<div class="page-heading"><div><div class="eyebrow">A LITTLE PROGRESS, EVERY DAY</div><h1>让理解，一点点发生。</h1><p>从今天的一个知识点开始，构建属于你的数学直觉。</p></div><div class="date-chip">${icon('calendar')}${esc(date)}</div></div><section class="hero"><div class="hero-copy"><span class="pill"><i></i>同济版 · 第八版 · 上下册</span><h2>从一个极限，<br>走进<em>微积分的世界。</em></h2><p>理清概念，拆解例题，在每一次练习中靠近答案。<br>让抽象的数学，成为可以看见、可以理解的规律。</p><div class="hero-actions"><a class="btn primary" href="#lesson/${l.id}">${state.completed.length||state.last!=='1-1'?'继续学习':'开始第一课'}${icon('arrow')}</a><a class="text-link" href="#courses">浏览完整课程${icon('chevron')}</a></div></div><div class="hero-art">${heroArt()}</div></section><div class="metrics">${[['book','12','体系章节'],['formula','82','知识小节'],['pen','164','随堂练习'],['lab','4','交互实验']].map(([ic,n,s])=>`<div class="metric"><div class="metric-icon">${icon(ic)}</div><div><strong>${n}</strong><span>${s}</span></div></div>`).join('')}</div><div class="section-head"><h2>${state.last==='1-1'&&!state.completed.length?'从这里开始':'继续上次学习'}<span>KEEP GOING</span></h2><a class="text-link" href="#progress">查看进度${icon('chevron')}</a></div><div class="continue-row"><a class="continue-card" href="#lesson/${l.id}"><div class="chapter-tile">${symbols[c.id-1]}</div><div class="continue-info"><div class="tiny">第 ${c.id} 章 · ${c.title}</div><h3>${l.chapter}.${l.number}　${esc(l.title)}</h3><p>概念讲解 · 例题拆解 · 2 道随堂练习</p></div><span class="round-link">${icon('arrow')}</span></a><div class="tip-card"><div class="tip-title">${icon('bulb')}学习小建议</div><p>先问“为什么”，再记“怎么做”。<br>公式的使用条件，和公式本身同样重要。</p><a href="#lab">去交互实验室寻找直觉 ↗</a></div></div><div class="section-head"><h2>你的学习路线<span>THE LEARNING PATH</span></h2>${volumeTabs()}</div><div id="home-chapters" class="chapter-grid">${filteredChapters().map(chapterCard).join('')}</div>`}
function volumeTabs(){return `<div class="tabs" role="group" aria-label="选择册次">${[['all','全部'],['upper','上册'],['lower','下册']].map(([id,t])=>`<button data-volume="${id}" class="${volume===id?'active':''}" aria-pressed="${volume===id}">${t}</button>`).join('')}</div>`}
function filteredChapters(){return chapters.filter(c=>volume==='all'||(volume==='upper'?c.id<=7:c.id>=8))}
function courses(){return `<div class="page-heading"><div><div class="eyebrow">BUILD YOUR FOUNDATION</div><h1>完整课程</h1><p>按照同济《高等数学》第八版的章节顺序，循序渐进。</p></div>${volumeTabs()}</div>${['上册','下册'].map((v,i)=>{let cs=filteredChapters().filter(c=>c.volume===v);return cs.length?`<div class="volume-label">${v} · ${i?'多元函数微积分与无穷级数':'一元函数微积分与微分方程'}</div><div class="chapter-grid">${cs.map(chapterCard).join('')}</div>`:''}).join('')}`}
function chapterPage(c){return `<div class="page-banner"><div class="eyebrow">CHAPTER ${String(c.id).padStart(2,'0')} / ${c.volume}</div><h1>${c.title}</h1><p>${c.description}</p><div class="chapter-summary"><span>${c.lessons.length} 节知识讲解</span><span>${c.lessons.length*2} 道练习</span><span>已学习 ${progress(c)} / ${c.lessons.length}</span></div></div><div class="section-head"><h2>本章目录</h2><a class="text-link" href="#practice/${c.id}">本章练习${icon('arrow')}</a></div><div class="lesson-list">${c.lessons.map(id=>{let l=byId[id],done=state.completed.includes(id);return `<a class="lesson-row" href="#lesson/${id}"><span class="lesson-no">${c.id}.${l.number}</span><div><h3>${esc(l.title)}${l.optional?'<span class="optional">选学</span>':''}</h3><p>预计 ${l.minutes} 分钟 · 例题 + 随堂练习</p></div><span class="lesson-status ${done?'done':''}">${done?'✓ 已学习':'开始学习 →'}</span></a>`}).join('')}</div><p class="tiny" style="margin-top:15px">“选学”对应教材中的星号节，可根据课程要求安排。</p>`}
function quizHTML(q,l){const a=state.answers[q.id],value=a?.value??'';return `<form class="quiz-card" data-quiz="${q.id}" novalidate><div class="quiz-meta"><span class="quiz-type">${q.type==='choice'?'选择题':'填空题'}</span><a href="#lesson/${l.id}">${l.chapter}.${l.number} ${esc(l.title)}</a></div><fieldset style="border:0;padding:0;margin:0"><legend class="quiz-prompt">${esc(q.prompt)}</legend>${q.type==='choice'?`<div class="quiz-options">${q.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="${q.id}" value="${i}" ${Number(value)===i&&value!==''?'checked':''}><span><span class="letter">${'ABCD'[i]}.</span> ${esc(o)}</span></label>`).join('')}</div>`:`<input class="fill-input" name="answer" value="${esc(value)}" aria-label="填写答案" placeholder="输入答案，分数可写成 1/2" autocomplete="off" inputmode="text">`}</fieldset><button type="submit" class="btn primary quiz-submit">${a?'重新提交':'提交答案'}</button><div class="feedback-slot" aria-live="polite">${a?feedback(q,a):''}</div></form>`}
function feedback(q,a){return `<div class="feedback ${a.correct?'':'wrong'}"><strong>${a.correct?'✓ 回答正确':'再想一想'}</strong>${!a.correct?`<span class="answer">正确答案：${q.type==='choice'?esc('ABCD'[q.correct]+'. '+q.options[q.correct]):esc(q.answers[0])}</span>`:''}<span>${esc(q.explain)}</span>${!a.correct?'<div>已加入错题，答对后会自动移出。</div>':''}</div>`}
function lessonPage(l){const c=chapters[l.chapter-1],idx=lessons.indexOf(l),prev=lessons[idx-1],next=lessons[idx+1],done=state.completed.includes(l.id),saved=state.bookmarks.includes(l.id);return `<div class="lesson-layout"><article class="article"><header class="article-header"><a class="text-link" href="#chapter/${c.id}">${icon('back')}第 ${c.id} 章 · ${c.title}</a><h1>${l.chapter}.${l.number}　${esc(l.title)}</h1><div class="article-meta"><span>知识讲解 + 例题 + 随堂练习</span><span>预计 ${l.minutes} 分钟</span>${l.optional?'<span>选学内容</span>':''}</div><div class="lesson-actions"><button class="btn ${done?'on':''}" data-complete="${l.id}">${icon('check')}${done?'已学习 · 点击撤销':'标记本节已学'}</button><button class="btn ${saved?'on':''}" data-bookmark="${l.id}">${icon('bookmark')}${saved?'已收藏':'收藏本节'}</button></div></header><section class="article-section" id="concept"><h2><span class="section-index">01</span>理解概念</h2><p>${esc(l.intro)}</p><div class="concept"><div class="concept-label">抓住核心</div>${esc(l.key)}</div></section><section class="article-section" id="formula"><h2><span class="section-index">02</span>关键公式</h2>${fbox(l.formula)}</section><section class="article-section" id="example"><h2><span class="section-index">03</span>跟着例题走一遍</h2><div class="example-box"><div class="example-prompt">${esc(l.example)}</div><ol class="example-steps">${l.steps.map((s,i)=>`<li><span class="step-number">${i+1}</span><span>${esc(s)}</span></li>`).join('')}</ol></div></section><section class="article-section" id="pitfall"><div class="notice">${icon('bulb')}<div><strong>易错提醒</strong><br>${esc(l.pitfall)}</div></div></section><section class="article-section" id="exercise"><h2><span class="section-index">04</span>现在，自己试试看</h2>${l.quiz.map(q=>quizHTML(q,l)).join('')}</section><div class="lesson-bottom">${prev?`<a class="btn" href="#lesson/${prev.id}">${icon('back')}上一节</a>`:'<span></span>'}${next?`<a class="btn primary" href="#lesson/${next.id}">下一节${icon('arrow')}</a>`:`<a class="btn primary" href="#progress">查看学习进度${icon('arrow')}</a>`}</div></article><aside class="lesson-aside"><div class="aside-panel"><div class="aside-label">本节导航</div>${[['concept','理解概念'],['formula','关键公式'],['example','例题拆解'],['pitfall','易错提醒'],['exercise','随堂练习']].map(([id,t])=>`<a href="#${route()}" data-scroll="${id}">${t}</a>`).join('')}</div><div class="aside-panel aside-course"><div class="aside-label">本章课程</div>${c.lessons.map(id=>`<a href="#lesson/${id}" class="${id===l.id?'current':''}">${byId[id].number}. ${esc(byId[id].title)}</a>`).join('')}</div><div class="aside-panel"><div class="aside-label">把知识放进图形里</div><a href="#lab" class="next-lesson">前往交互实验室 →</a></div></aside></div>`}
function practice(){const c=chapters[practiceCh-1],ls=c.lessons.map(id=>byId[id]);return `<div class="page-heading"><div><div class="eyebrow">LEARN BY DOING</div><h1>随堂练习</h1><p>先想清楚，再提交。每一道错题都是重新理解的机会。</p></div></div><div class="practice-toolbar"><label>选择章节 <select class="select" id="practice-chapter">${chapters.map(ch=>`<option value="${ch.id}" ${ch.id===practiceCh?'selected':''}>第 ${ch.id} 章 · ${esc(ch.title)}</option>`).join('')}</select></label><div class="tabs" role="group" aria-label="练习类型">${[['all','全部题型'],['choice','选择题'],['fill','填空题']].map(([id,t])=>`<button data-practice-type="${id}" class="${practiceType===id?'active':''}">${t}</button>`).join('')}</div></div><div class="prose">${ls.map(l=>l.quiz.filter(q=>practiceType==='all'||q.type===practiceType).map(q=>quizHTML(q,l)).join('')).join('')}</div>`}
function review(){const ids=wrong();return `<div class="page-heading"><div><div class="eyebrow">REVISIT & UNDERSTAND</div><h1>错题与收藏</h1><p>回头看一次，把薄弱的地方慢慢补起来。</p></div></div><div class="tabs review-tabs" role="group" aria-label="复习类型">${[['wrong',`错题本 · ${ids.length}`],['bookmarks',`课程收藏 · ${state.bookmarks.length}`]].map(([id,t])=>`<button data-review="${id}" class="${reviewTab===id?'active':''}">${t}</button>`).join('')}</div>${reviewTab==='wrong'?(ids.length?`<div class="prose">${ids.map(id=>{const q=qById[id];return quizHTML(q,q.lesson)}).join('')}</div>`:empty('pen','目前没有待复习的错题','完成随堂练习后，答错的题会自动汇集在这里。','去做几道练习','#practice')):(state.bookmarks.length?`<div class="lesson-list">${state.bookmarks.map(id=>{let l=byId[id];return `<a class="lesson-row" href="#lesson/${id}"><span class="lesson-no">${l.chapter}.${l.number}</span><div><h3>${esc(l.title)}</h3><p>${chapters[l.chapter-1].title}</p></div><span class="lesson-status">去复习 →</span></a>`}).join('')}</div>`:empty('bookmark','收藏值得再读的一节','在课程中点击“收藏本节”，就能在这里找到它。','浏览课程','#courses'))}`}
function empty(ic,title,p,t,href){return `<div class="empty">${icon(ic)}<h2>${title}</h2><p>${p}</p><a class="btn primary" href="${href}">${t}${icon('arrow')}</a></div>`}
function formulas(){const ls=lessons.filter(l=>!formulaCh||l.chapter===formulaCh);return `<div class="page-heading"><div><div class="eyebrow">YOUR QUICK REFERENCE</div><h1>公式手册</h1><p>把关键公式放在一起，也别忘记它们的使用条件。</p></div></div><div class="practice-toolbar"><label>按章节查阅 <select class="select" id="formula-chapter"><option value="0">全部章节</option>${chapters.map(c=>`<option value="${c.id}" ${formulaCh===c.id?'selected':''}>${c.id}. ${esc(c.title)}</option>`).join('')}</select></label><button class="btn" data-action="search">${icon('search')}搜索知识点</button></div><div class="formula-grid">${ls.map(l=>`<a href="#lesson/${l.id}" class="formula-card"><span class="tiny">${l.chapter}.${l.number} · ${chapters[l.chapter-1].title}</span><h3>${esc(l.title)}</h3>${fbox(l.formula)}<span class="tiny">查看概念、适用条件与例题 →</span></a>`).join('')}</div>`}
function progressPage(){const a=Object.values(state.answers),correct=a.filter(x=>x.correct).length;return `<div class="page-heading"><div><div class="eyebrow">YOUR OWN PACE</div><h1>每一步，都算数。</h1><p>学习记录保存在当前浏览器中，按自己的节奏继续。</p></div><button class="btn" data-action="export">${icon('download')}导出进度</button></div><div class="progress-summary"><div><strong>${state.completed.length}<small> / 82</small></strong><small>已学习小节</small></div><div><strong>${a.length}<small> / 164</small></strong><small>已作答题目</small></div><div><strong>${a.length?pct(correct,a.length)+'%':'—'}</strong><small>最近一次答案正确率</small></div></div><div class="lesson-list">${chapters.map(c=>`<a class="lesson-row" href="#chapter/${c.id}"><span class="lesson-no">${String(c.id).padStart(2,'0')}</span><div style="flex:1"><h3>${esc(c.title)}</h3><div class="bar" style="margin-top:9px;max-width:320px"><b style="width:${pct(progress(c),c.lessons.length)}%"></b></div></div><span class="lesson-status">${progress(c)} / ${c.lessons.length} 节</span></a>`).join('')}</div><p class="tiny" style="margin-top:17px">已学习由你在课程中手动标记；正确率以每道已作答题的最近一次提交为准。</p>`}
function about(){return `<div class="page-heading"><div><div class="eyebrow">ABOUT ZHIWEI</div><h1>关于知微</h1><p>从微小的变化里，看见数学的秩序。</p></div></div><article class="prose"><h2>课程体系</h2><p>知微依照同济大学数学科学学院《高等数学》第八版上、下册目录组织，共12章、82节。带“选学”标签的课程对应教材中的星号节。课程包含独立编写的概念讲解、公式、例题和164道选择及填空练习，适合配合教材学习与复习。</p><p>目录依据：<a href="https://xuanshu.hep.com.cn/front/book/findBookDetails?bookId=62cdab46938b7cc2960eedb1" target="_blank" rel="noopener">高教社·第八版上册</a>、<a href="https://xuanshu.hep.com.cn/front/book/findBookDetails?bookId=62bc8b97938b7cc2960eebb7" target="_blank" rel="noopener">高教社·第八版下册</a>。网站是独立学习辅助工具。</p><h2>如何学习</h2><p>建议按章节顺序阅读，先理解概念与公式条件，再跟着例题完成推导，最后独立做题。你可以把已经理解的小节标为“已学习”，收藏需要复看的课程，并到交互实验室观察极限、切线、黎曼和与傅里叶逼近。</p><h2>关于练习与进度</h2><p>选择题每题只有一个正确选项。填空题接受普通数字、小数与简单分数，例如“1/2”和“0.5”视为相同；不需要输入单位。答错的题自动进入错题本，重新答对后自动移出。浏览器会记录最近一次答案、收藏与已学小节。</p><p>记录仅保存在当前设备、当前浏览器中。清理网站数据或更换浏览器会影响记录，你可以在学习进度页导出一份JSON备份。当前版本的备份用于留存与查看。</p><a class="btn primary" href="#lesson/${state.last}">开始学习${icon('arrow')}</a></article>`}
const labs={limit:{title:'极限，不是到达，而是靠近。',desc:'让 h 越来越接近 0，观察 sin(h)/h 如何趋近 1。图像中的空心圆提醒我们：原式在 0 处没有定义。',label:'距原点的距离 h',min:.01,max:2,step:.01,value:1,end:['更靠近 0','离原点更远'],unit:'h = ',graph:'sin(x) / x 的极限',note:'蓝点的横坐标为 h；灰色虚线标出极限值 y = 1。',lesson:'1-6'},tangent:{title:'让割线的直觉，变成切线。',desc:'拖动切点，观察 y = x² 的切线斜率。切线在一点附近近似曲线，斜率随着横坐标线性变化。',label:'切点横坐标 a',min:-2,max:2,step:.05,value:1,end:['−2','2'],unit:'a = ',graph:'抛物线与它的切线',note:'蓝色为曲线 y = x²，金色直线为选定点处的切线。',lesson:'2-1'},integral:{title:'把曲线下的面积，一小块一小块加起来。',desc:'用右端点矩形逼近 y = x² 在 [0, 2] 上的积分。矩形越细，累积和就越接近真实积分 8/3。',label:'矩形数量 n',min:2,max:80,step:1,value:8,end:['2 个','80 个'],unit:'n = ',graph:'右端点黎曼和',note:'蓝色矩形取每段右端点的函数值；本例中右端点和大于真实积分。',lesson:'5-1'},series:{title:'用一条条正弦波，拼出方波。',desc:'把更多奇次谐波加在一起，观察傅里叶部分和如何逼近方波。跳跃点附近的振荡是吉布斯现象。',label:'奇次谐波项数 N',min:1,max:20,step:1,value:3,end:['1 项','20 项'],unit:'N = ',graph:'方波的傅里叶逼近',note:'在跳跃点，级数趋于左右极限的平均值0；过冲幅度不会随项数增加完全消失。',lesson:'12-7'}};
function labPage(){const l=labs[labType];return `<div class="page-heading"><div><div class="eyebrow">SEE THE MATH HAPPEN</div><h1>交互实验室</h1><p>动一动参数，让抽象的概念在眼前发生。</p></div></div><div class="tabs lab-tabs" role="group" aria-label="选择实验">${[['limit','极限逼近'],['tangent','曲线与切线'],['integral','黎曼和'],['series','级数逼近']].map(([id,t])=>`<button data-lab="${id}" class="${labType===id?'active':''}" aria-pressed="${labType===id}">${t}</button>`).join('')}</div><div class="lab-layout"><div class="graph-panel"><div class="graph-head"><h2>${l.graph}</h2><small>INTERACTIVE EXPLORATION</small></div><svg id="lab-graph" class="graph" viewBox="0 0 650 450" role="img" aria-label="${l.graph}"></svg><div class="graph-foot">${l.note}</div></div><section class="lab-control"><div class="control-copy"><h3>${l.title}</h3><p>${l.desc}</p></div><div><label class="range-label" for="lab-range"><span>${l.label}</span><output id="range-output">${l.unit}${l.value}</output></label><input type="range" id="lab-range" min="${l.min}" max="${l.max}" step="${l.step}" value="${l.value}" aria-label="${l.label}"><div class="range-endpoints"><span>${l.end[0]}</span><span>${l.end[1]}</span></div></div><div class="readout" id="lab-readout" aria-live="polite"></div><div class="lab-context"><p>把直觉与定义连起来</p><a href="#lesson/${l.lesson}">学习：${byId[l.lesson].title} →</a></div></section></div>`}
function drawLab(){const svg=document.getElementById('lab-graph');if(!svg)return;const v=Number(document.getElementById('lab-range').value),l=labs[labType];document.getElementById('range-output').value=l.unit+(Number.isInteger(v)?v:v.toFixed(2));let bounds=labType==='limit'?[-6,6,-.4,1.6]:labType==='tangent'?[-3,3,-1,7]:labType==='integral'?[-.25,2.3,-.5,5]:[-Math.PI*1.2,Math.PI*1.2,-1.7,1.7];let [xmin,xmax,ymin,ymax]=bounds,W=650,H=450,pad=48,X=x=>pad+(x-xmin)/(xmax-xmin)*(W-2*pad),Y=y=>H-pad-(y-ymin)/(ymax-ymin)*(H-2*pad);let out=`<defs><clipPath id="plot-clip"><rect x="${pad}" y="${pad}" width="${W-2*pad}" height="${H-2*pad}"/></clipPath></defs>`;const line=(x1,y1,x2,y2,col='#e9edf6',width=1,dash='')=>`<path d="M${X(x1)} ${Y(y1)}L${X(x2)} ${Y(y2)}" fill="none" stroke="${col}" stroke-width="${width}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
let gx=labType==='integral'?.5:1,gy=labType==='limit'?.25:1;for(let x=Math.ceil(xmin/gx)*gx;x<=xmax;x+=gx){out+=line(x,ymin,x,ymax);if(x!==0)out+=`<text x="${X(x)}" y="${Y(0)+18}" font-size="10" text-anchor="middle" fill="#a0adc4">${x}</text>`}for(let y=Math.ceil(ymin/gy)*gy;y<=ymax;y+=gy){out+=line(xmin,y,xmax,y);if(y!==0)out+=`<text x="${X(0)-10}" y="${Y(y)+3}" font-size="10" text-anchor="end" fill="#a0adc4">${y}</text>`}out+=line(xmin,0,xmax,0,'#aebdd6',1.1)+line(0,ymin,0,ymax,'#aebdd6',1.1);out+=`<text x="${X(xmax)-5}" y="${Y(0)-9}" fill="#91a3c3" font-size="12" font-family="Georgia" font-style="italic">x</text>`;const curve=(fn,col='#3158c9',width=2.6)=>{let d='';for(let i=0;i<=700;i++){let x=xmin+(xmax-xmin)*i/700,y=fn(x);if(!Number.isFinite(y)){d+=' ';continue}d+=(i?'L':'M')+X(x).toFixed(2)+' '+Y(y).toFixed(2)}return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${width}" stroke-linejoin="round"/>`};const dot=(x,y)=>`<circle cx="${X(x)}" cy="${Y(y)}" r="9" fill="#3158c9" opacity=".12"/><circle cx="${X(x)}" cy="${Y(y)}" r="4.5" fill="#3158c9" stroke="white" stroke-width="2"/>`;let read='';out+='<g clip-path="url(#plot-clip)">';if(labType==='limit'){out+=line(xmin,1,xmax,1,'#a5b4d0',1.2,'5 5')+curve(x=>Math.abs(x)<1e-8?1:Math.sin(x)/x);let y=Math.sin(v)/v;out+=line(v,0,v,y,'#a7b8de',1,'3 4')+dot(v,y)+`<circle cx="${X(0)}" cy="${Y(1)}" r="4" fill="white" stroke="#3158c9" stroke-width="2"/>`;read=`当前 sin(h) / h<strong>${y.toFixed(6)}</strong><span>与极限 1 的距离：${Math.abs(1-y).toFixed(6)}</span>`}else if(labType==='tangent'){out+=curve(x=>x*x)+curve(x=>2*v*x-v*v,'#c49b63',1.7)+dot(v,v*v);read=`切线斜率 f ′(a) = 2a<strong>${(2*v).toFixed(2)}</strong><span>切点：(${v.toFixed(2)}, ${(v*v).toFixed(2)})</span>`}else if(labType==='integral'){let dx=2/v,sum=0;for(let i=0;i<v;i++){let x=i*dx,y=((i+1)*dx)**2;sum+=y*dx;out+=`<rect x="${X(x)}" y="${Y(y)}" width="${X(x+dx)-X(x)}" height="${Y(0)-Y(y)}" fill="#e0e8fc" stroke="#91a9df" stroke-width=".8"/>`}out+=curve(x=>x*x);read=`右端点和<strong>${sum.toFixed(6)}</strong><span>真实积分：2.666667<br>误差：${(sum-8/3).toFixed(6)}</span>`}else{for(let k=-1;k<=1;k++){let a=k*Math.PI,b=(k+1)*Math.PI;out+=line(a,k%2===0?1:-1,b,k%2===0?1:-1,'#b7c3d9',1.5,'5 4')}out+=curve(x=>{let s=0;for(let n=0;n<v;n++){let k=2*n+1;s+=Math.sin(k*x)/k}return 4/Math.PI*s});read=`方波部分和：奇次谐波<strong>${v} 项</strong><span>最高频率为 ${2*v-1}；跳跃点的极限值为 0。</span>`}out+='</g>';svg.innerHTML=out;document.getElementById('lab-readout').innerHTML=read}
function notFound(){return `<div class="not-found"><h1>还没找到这节课程</h1><p>请从完整课程目录选择一个知识点。</p><a class="btn primary" href="#courses">返回课程目录</a></div>`}
function render(keepScroll=false){let [page,arg]=route().split('/'),html;document.body.classList.remove('menu-open');if(page==='courses'&&['upper','lower'].includes(arg))volume=arg;if(page==='practice'&&arg&&chapters[Number(arg)-1])practiceCh=Number(arg);if(page==='home')html=home();else if(page==='courses')html=courses();else if(page==='chapter')html=chapters[Number(arg)-1]?chapterPage(chapters[Number(arg)-1]):notFound();else if(page==='lesson'){let l=byId[arg];if(l){state.last=l.id;save();html=lessonPage(l)}else html=notFound()}else if(page==='practice')html=practice();else if(page==='formulas')html=formulas();else if(page==='review')html=review();else if(page==='lab')html=labPage();else if(page==='about')html=about();else if(page==='progress')html=progressPage();else html=notFound();sidebar();let main=document.getElementById('main');main.innerHTML=html;document.title=(page==='lesson'&&byId[arg]?byId[arg].title+' · ':'')+'知微 · 高等数学';math();if(page==='lab')drawLab();if(!keepScroll)window.scrollTo(0,0)}
function searchResults(value){let q=value.trim().toLowerCase(),ls;if(!q)ls=['1-6','2-1','3-3','5-2','9-7','12-7'].map(id=>byId[id]);else ls=lessons.map(l=>{let text=l.title.toLowerCase();return {l,score:(text.includes(q)?10:0)+([l.intro,l.key,l.formula,chapters[l.chapter-1].title,l.id].some(t=>t.toLowerCase().includes(q))?1:0)}}).filter(x=>x.score).sort((a,b)=>b.score-a.score).map(x=>x.l).slice(0,24);document.getElementById('search-results').innerHTML=ls.length?`${!q?'<div class="tiny" style="padding:8px 12px">推荐从这些概念开始</div>':''}${ls.map(l=>`<a class="search-result" href="#lesson/${l.id}" data-search-result><strong>${l.chapter}.${l.number}　${esc(l.title)}</strong><small>${chapters[l.chapter-1].title}</small></a>`).join('')}`:'<div class="search-empty">没有找到相关知识点，试试“极限”“导数”或“积分”。</div>';math(document.getElementById('search-results'))}
function openSearch(){const d=document.getElementById('search-dialog');if(!d.open)d.showModal();let input=document.getElementById('search-input');input.value='';searchResults('');input.focus()}
function numberValue(s){const n=String(s).normalize('NFKC').trim().replace(/\s/g,'').replace(/[−–]/g,'-').replace(/[，,]/g,'').replace(/^\$|\$$/g,'');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:\/[+-]?(?:\d+(?:\.\d*)?|\.\d+))?$/.test(n))return NaN;let p=n.split('/').map(Number);return p.length===2?p[1]===0?NaN:p[0]/p[1]:p[0]}
function isCorrect(q,v){if(q.type==='choice')return Number(v)===q.correct;return q.answers.some(a=>{let x=numberValue(v),y=numberValue(a);return Number.isFinite(x)&&Number.isFinite(y)?Math.abs(x-y)<=1e-8*Math.max(1,Math.abs(y)):String(v).trim()===a.trim()})}
document.addEventListener('click',e=>{let el=e.target.closest('button,a');if(!el)return;if(el.dataset.scroll){e.preventDefault();document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}if(el.dataset.searchResult!==undefined){document.getElementById('search-dialog').close();return}if(el.dataset.volume){volume=el.dataset.volume;if(route().startsWith('courses/')){history.replaceState(null,'','#courses');}render(true);return}if(el.dataset.complete){const id=el.dataset.complete;if(state.completed.includes(id)){state.completed=state.completed.filter(v=>v!==id);toast('已取消已学标记')}else{state.completed.push(id);state.activity[id]=new Date().toISOString();toast('已记录学习进度，继续加油。')}save();render(true);return}if(el.dataset.bookmark){let id=el.dataset.bookmark;if(state.bookmarks.includes(id)){state.bookmarks=state.bookmarks.filter(x=>x!==id);toast('已取消收藏')}else{state.bookmarks.push(id);toast('已收藏，可在“错题与收藏”中查看')}save();render(true);return}if(el.dataset.review){reviewTab=el.dataset.review;render(true);return}if(el.dataset.practiceType){practiceType=el.dataset.practiceType;render(true);return}if(el.dataset.lab){labType=el.dataset.lab;render(true);return}if(el.dataset.action==='search')openSearch();if(el.dataset.action==='menu'){let on=document.body.classList.toggle('menu-open');el.setAttribute('aria-expanded',String(on))}if(el.dataset.action==='export'){const blob=new Blob([JSON.stringify({site:'知微 · 高等数学',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='知微-高等数学-学习进度.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习进度已导出')}});
document.addEventListener('submit',e=>{let form=e.target.closest('[data-quiz]');if(!form)return;e.preventDefault();let q=qById[form.dataset.quiz];const input=q.type==='choice'?form.querySelector('input:checked'):form.querySelector('input[name="answer"]');if(!input||!input.value.trim()){toast(q.type==='choice'?'先选择一个答案，再提交。':'先填写答案，再提交。');form.querySelector('input')?.focus();return}let a={value:input.value,correct:isCorrect(q,input.value),at:new Date().toISOString()};state.answers[q.id]=a;save();let slot=form.querySelector('.feedback-slot');slot.innerHTML=feedback(q,a);math(slot);form.querySelector('button[type=submit]').textContent='重新提交';sidebar();if(a.correct&&route().startsWith('review')){render(true);toast('答对了，这道题已从错题本移出。')}});
document.addEventListener('change',e=>{if(e.target.id==='practice-chapter'){practiceCh=Number(e.target.value);if(route()!=='practice')location.hash='practice';else render(true)}if(e.target.id==='formula-chapter'){formulaCh=Number(e.target.value);render(true)}});
document.addEventListener('input',e=>{if(e.target.id==='search-input')searchResults(e.target.value);if(e.target.id==='lab-range')drawLab()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape')document.body.classList.remove('menu-open');if(e.key==='Enter'&&e.target.id==='search-input'){e.preventDefault();let a=document.querySelector('[data-search-result]');if(a){document.getElementById('search-dialog').close();location.hash=a.getAttribute('href')}}});
document.getElementById('search-icon').innerHTML=icon('search');document.getElementById('search-dialog').addEventListener('click',e=>{if(e.target.id==='search-dialog')e.target.close()});window.addEventListener('hashchange',()=>render());render();
window.ZHIWEI={isCorrect,numberValue,render,drawLab,getState:()=>JSON.parse(JSON.stringify(state))};
})();
